y=df.set_index('date')['sales_units'].asfreq('MS')
models={}
for trend in [None,'add','mul']:
    for seasonal in [None,'add','mul']:
        if seasonal is None or len(y)>=24:
            try:
                fit=ExponentialSmoothing(y, trend=trend, seasonal=seasonal, seasonal_periods=12 if seasonal else None, damped_trend=(trend is not None), initialization_method='estimated').fit(optimized=True)
                fc=fit.forecast(3)
                models[(trend,seasonal)]=(fit.aic, fc.iloc[-1], fc.values)
