import statsmodels.api as sm
# SARIMA grid small on log
logy=np.log(y)
best=[]
for p in range(3):
 for d in [0,1]:
  for q in range(3):
   for P in range(2):
    for D in [0,1]:
     for Q in range(2):
      if p==q==P==Q==0 and d==D==0: continue
      try:
       mod=sm.tsa.SARIMAX(logy, order=(p,d,q), seasonal_order=(P,D,Q,12), trend='c' if d==0 and D==0 else 'n',
                          enforce_stationarity=False, enforce_invertibility=False)
       fit=mod.fit(disp=False, maxiter=200)
       fc=np.exp(fit.get_forecast(3).predicted_mean.iloc[-1])
       best.append((fit.aic,(p,d,q),(P,D,Q),fc,np.exp(fit.get_forecast(3).predicted_mean).values))
      except Exception as e: pass
sorted(best)[:10]
